@Service
class RetryService {

    suspend fun fetchWithRetry(url: String): String {
        repeat(3) { attempt ->
            try {
                return httpClient.get(url)
            } catch (e: IOException) {
                Thread.sleep(1000L * (attempt + 1))
            }
        }
        throw IOException("全試行に失敗しました")
    }
}
